public interface IIdempotentConsumer
{
    bool TryClaim(string messageId);
    void Release(string messageId);
}

public sealed class IdempotentConsumer : IIdempotentConsumer
{
    private readonly object _sync = new();
    private readonly HashSet<string> _claimed = new();
    private readonly TimeSpan _ttl;
    private readonly TimeProvider _time;
    private readonly Dictionary<string, DateTimeOffset> _expires = new();

    public IdempotentConsumer(TimeSpan? ttl = null, TimeProvider? time = null)
    {
        _ttl = ttl ?? TimeSpan.FromHours(24);
        _time = time ?? TimeProvider.System;
    }

    public bool TryClaim(string messageId)
    {
        lock (_sync)
        {
            PruneExpired();
            if (_claimed.Contains(messageId)) return false;
            _claimed.Add(messageId);
            _expires[messageId] = _time.GetUtcNow().Add(_ttl);
            return true;
        }
    }

    public void Release(string messageId)
    {
        lock (_sync)
        {
            _claimed.Remove(messageId);
            _expires.Remove(messageId);
        }
    }

    private void PruneExpired()
    {
        var now = _time.GetUtcNow();
        foreach (var kv in _expires.ToList())
        {
            if (kv.Value <= now)
            {
                _claimed.Remove(kv.Key);
                _expires.Remove(kv.Key);
            }
        }
    }
}
